#!/usr/bin/env node
// BURGER SKIN — установщик кинодропов (v3).
// Установка: node install-cinematic.mjs        Проверка: node install-cinematic.mjs --check
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const FILES = {"src/lib/dropfx.ts":{"sha":"76e2c317754a1fe7022c90da9c8ead7e21a9bbe4352379b7a633c0fd59a76d37","b64":""},"src/lib/core.ts":{"sha":"1f6cdca6a531a0138e607d0957d024420eea321d9e0cc1e7014c0d3926b43bc1","b64":""},"src/lib/cases.ts":{"sha":"b34c4dc69007559fdf0558d2ae871d720516d639eef6a88e3c36b52f5dea92c5","b64":""},"src/routes/play.ts":{"sha":"90a3d18dc5a7566024a491c1fb816d20ba19c23e76e5836441fe1d67916cfc26","b64":""},"src/routes/admin.ts":{"sha":"760be0cfcb6da4991855a0ef36568912c61bb7f5b2fabc7cb8716019bb9c2992","b64":""},"src/routes/social.ts":{"sha":"8f7998196fe8ec7a95a63e6185b5c262b5392c459be6fd2d7936afbf629b5e81","b64":""},"src/routes/auth.ts":{"sha":"b60aefba5232cf2ed126b18e746d3c5064e06cae9a5f67ac7eaf3e6c0436bd4c","b64":""},"src/server.ts":{"sha":"4de7efc153ed61d5aef15a098f0824b89f310e29e846351acedfb9b5336eebf0","b64":""},"public/index.html":{"sha":"b9596bc8bf0a0d54062f0df9221d75158b89c9407e73d999efb2f00f0c9fbf6f","b64":""},"public/cine.css":{"sha":"5cfef576f1ab0794dc998d912b357dfe02abb61fdc56c3b0f976e4f7f59dff06","b64":""},"public/app.css":{"sha":"074e0c2ebffea7db7c38b3db09fdacc7cfca3bc631273081587eced41e752669","b64":""},"public/js/sound.js":{"sha":"826b40a6cb57a41baa30fa4b88467af6f104e071e04134156e7452ace9b7d599","b64":""},"public/js/cine-sound.js":{"sha":"69ae4524094bfd1ba6603cc1fefe0b8a336829482b48eddc94f4d72def4b17b1","b64":""},"public/js/cine-mode.js":{"sha":"5eb8afb52b1a1f864000dd29890235891575899951648bfe8953392f57b1f23a","b64":""},"public/js/cinematic.js":{"sha":"de47c5bd3520945c08934b1de1811cd197855e835011eca59543f9a4b5c87375","b64":""},"public/js/app.js":{"sha":"90c6a2f2883e60f5f65c317a96cad2bc8ab8f49539964c9ea16b283fc82428dd","b64":""},"public/js/core.js":{"sha":"b3bb11a341e758c6e5f7c90933f946b43f0e96d77b81fe320e70fa943c5b5d38","b64":""},"public/js/pages/main.js":{"sha":"0bcd0b3e61e3ccbe2aff1489e86a284ea7088b7383e8953d7059647dedefb48f","b64":""},"public/js/pages/drop.js":{"sha":"c41ae30244783a334ad5730708a4e08eac8f08715271476ecb8e82311aad8ab5","b64":""},"public/js/pages/admin-drops.js":{"sha":"8e48698a55485bbd17bbfbb0662eb98f5c1f88bb9beb24c6c2f4d05989a7a3e3","b64":""},"public/js/pages/admin-ui.js":{"sha":"15742d707dbbfc77109730f8584a307e5925c9a281da5d2f0145dea6ddd7fb64","b64":""},"public/js/pages/admin4.js":{"sha":"d0431c64dca1171fb83c7072c069cc35089345df27c74ee3cad0323d94a88553","b64":""},"scripts/cine-test.ts":{"sha":"b0e5bd95053a5236dcb9ef5c733a062456de5ed282aa99795f04ce8848d199ae","b64":""}};

const here = path.dirname(fileURLToPath(import.meta.url));
const isProj = (d) => {
  try {
    const p = JSON.parse(fs.readFileSync(path.join(d, 'package.json'), 'utf8'));
    return p.name === 'burger-skin' && fs.existsSync(path.join(d, 'src', 'server.ts')) && fs.existsSync(path.join(d, 'public', 'js', 'app.js'));
  } catch { return false; }
};
const root = [process.cwd(), here, path.dirname(here), path.dirname(process.cwd())].find(isProj);
if (!root) {
  console.error('\nОШИБКА: не найден проект BURGER SKIN (папка с package.json и src/server.ts).');
  console.error('Положите install-cinematic.mjs в папку проекта (там, где package.json) и запустите: node install-cinematic.mjs\n');
  process.exit(1);
}
const sha = (b) => crypto.createHash('sha256').update(b).digest('hex');
const cur = (rel) => { try { return sha(fs.readFileSync(path.join(root, rel))); } catch { return null; } };
console.log('Проект: ' + root);

if (process.argv.includes('--check')) {
  let bad = 0;
  for (const [rel, f] of Object.entries(FILES)) {
    const h = cur(rel);
    const st = h === f.sha ? 'OK        ' : h ? 'ОТЛИЧАЕТСЯ' : 'НЕТ ФАЙЛА';
    if (h !== f.sha) bad++;
    console.log('  ' + st + '  ' + rel);
  }
  console.log(bad ? '\nКинодропы установлены не полностью (' + bad + '). Запустите: node install-cinematic.mjs' : '\nВсе файлы кинодропов на месте.');
  process.exit(bad ? 1 : 0);
}

const d = new Date(), p2 = (n) => String(n).padStart(2, '0');
const stamp = d.getFullYear() + p2(d.getMonth() + 1) + p2(d.getDate()) + '-' + p2(d.getHours()) + p2(d.getMinutes()) + p2(d.getSeconds());
const bdir = path.join(root, 'backups', 'cinematic-' + stamp);
let changed = 0, same = 0, saved = 0;
for (const [rel, f] of Object.entries(FILES)) {
  const dst = path.join(root, rel);
  const h = cur(rel);
  if (h === f.sha) { same++; continue; }
  if (h) { const b = path.join(bdir, rel); fs.mkdirSync(path.dirname(b), { recursive: true }); fs.copyFileSync(dst, b); saved++; }
  fs.mkdirSync(path.dirname(dst), { recursive: true });
  fs.writeFileSync(dst, Buffer.from(f.b64, 'base64'));
  if (cur(rel) !== f.sha) { console.error('Не удалось записать ' + rel + ' (файл занят или нет прав)'); process.exit(1); }
  changed++;
  console.log('  обновлён  ' + rel);
}
console.log('\nГотово: обновлено ' + changed + ', уже актуальны ' + same + '.' + (saved ? ' Старые версии (' + saved + ') сохранены в ' + path.relative(root, bdir) : ''));
console.log('\nДальше:');
console.log('  1) Остановите сервер (Ctrl+C в окне, где он запущен) и снова запустите: npm start');
console.log('  2) В браузере один раз нажмите Ctrl+F5 (дальше обновления подхватываются сами)');
console.log('  3) Откройте /admin/drops — там пороги и кнопки «Показать» для каждой сцены');
